export type IconType = keyof typeof iconMap;

export interface IconProps {
  type: IconType;
  className?: string;
  width?: number;
  height?: number;
  onClick?: (e?: unknown) => void;
  active?: boolean;
  alt?: string;
  role?: 'img' | 'presentation';
  ariaLabel?: string;
  priority?: boolean;
}

export const Icon: FC<IconProps> = ({
  type,
  width,
  height,
  role = 'img',
  ariaLabel,
  priority: _priority,
  alt: _alt,
  ...other
}) => {
  const IconComponent = iconMap[type];
  const uniqueId = useId();
  const description = ariaLabel || type;
  if (!IconComponent) {
    return null;
  }

  return (
    <IconComponent
      width={width}
      height={height}
      data-testid="icon"
      {...other}
      role={role}
      aria-label={role !== 'presentation' ? description : undefined}
      id={`icon-${uniqueId}`}
    />
  );
};

export default Icon;
